    "productDetails": "{\n  \"size\": \"30мл\",\n  \"skinType\": \"Чувствительная, реактивная и легко раздражаемая кожа\",\n  \"formulation\": \"Мягкая, не раздражающая сыворотка\",\n  \"keyBenefits\": \"Восстановление барьера, противовоспалительное действие, успокаивающий эффект\",\n  \"origin\": \"Южная Корея\"\n}",
