    "ingredients": "[\n  {\n    \"name\": \"Hyaluronan 11 Multi-Complex\",\n    \"description\": \"Продвинутый комплекс гиалуроновой кислоты с низким, средним и высоким молекулярными весами для комплексной гидратации и защиты кожи.\"\n  },\n  {\n    \"name\": \"Экстракты грибов\",\n    \"description\": \"Различные экстракты грибов обеспечивают мощные противовоспалительные и антиоксидантные свойства для питания и защиты кожи.\"\n  },\n  {\n    \"name\": \"Технология магнита влаги\",\n    \"description\": \"Специальные ингредиенты, которые привлекают и удерживают влагу, создавая резервуар влаги в коже для устойчивой гидратации.\"\n  },\n  {\n    \"name\": \"Натуральные охлаждающие агенты\",\n    \"description\": \"Охлаждающие агенты натурального происхождения обеспечивают мгновенное освежение кожи и помогают снизить температуру кожи для освежающего ощущения.\"\n  }\n]",
    "howToUse": "[\n  {\n    \"step\": \"Очищение\",\n    \"instruction\": \"Начните с чистой, сухой кожи\"\n  },\n  {\n    \"step\": \"Применение\",\n    \"instruction\": \"Возьмите небольшое количество и аккуратно помассируйте на лицо и шею\"\n  },\n  {\n    \"step\": \"Массаж\",\n    \"instruction\": \"Используйте восходящие круговые движения до полного впитывания\"\n  },\n  {\n    \"step\": \"Частота использования\",\n    \"instruction\": \"Используйте утром и вечером для достижения наилучших результатов\"\n  },\n  {\n    \"step\": \"Дальнейший уход\",\n    \"instruction\": \"Нанесите солнцезащитный крем в дневное время\"\n  }\n]",
