    "productDetails": "{\n  \"type\": \"Антивозрастной набор для ухода за кожей\",\n  \"size\": \"1 набор\",\n  \"keyBenefits\": \"Улучшение упругости, разглаживание тонких линий, повышение эластичности, омоложение кожи\",\n  \"skinType\": \"Всех типов кожи, особенно зрелой и стареющей\",\n  \"usage\": \"Ежедневный антивозрастной уход\",\n  \"origin\": \"Южная Корея\"\n}",
